import 'dart:convert';import 'dart:io';import 'package:flutter/services.dart';import '../domain/article.dart';import 'content_update_service.dart';
class ArticleRepository{ArticleRepository({ContentUpdateService? updater}):_updater=updater??ContentUpdateService();final ContentUpdateService _updater;Future<List<Article>> load()async{String? payload;try{final file=await _updater.activeFile('articles/index.json');if(file!=null)payload=await file.readAsString();}catch(_){}payload??=await rootBundle.loadString('assets/content/articles.json');final decoded=jsonDecode(payload);if(decoded is! Map||decoded['schema_version']!=1||decoded['articles'] is! List)throw const FormatException('Article catalog schema is invalid.');final ids=<String>{};final articles=<Article>[];for(final raw in decoded['articles']){if(raw is! Map)throw const FormatException('Invalid article item.');final article=Article.fromMap(Map<String,dynamic>.from(raw));if(article.id.isEmpty||article.title.isEmpty||article.blocks.isEmpty||!ids.add(article.id))throw const FormatException('Article metadata is incomplete or duplicated.');articles.add(article);}return articles;}
void dispose()=>_updater.close();}
